public void initValue()
{
    super();

    this.CalendarDataAreaId     = curext();
    this.EmploymentCoefficient = 1.0;
    this.ValidFrom              = systemDateGet();
    this.ValidTo                = dateMax();
}

public boolean validateWrite()
{
    boolean ret = super();

    if (!this.Worker)
    {
        ret = checkFailed("Worker is required.");
    }

    if (ret && !this.CalendarDataAreaId)
    {
        ret = checkFailed("Calendar legal entity is required.");
    }

    if (ret && !this.CalendarId)
    {
        ret = checkFailed("Calendar is required.");
    }

    if (ret && this.EmploymentCoefficient <= 0)
    {
        ret = checkFailed("Employment coefficient must be greater than zero.");
    }

    if (ret && (!this.ValidFrom || !this.ValidTo))
    {
        ret = checkFailed("From date and To date are required.");
    }

    if (ret && this.ValidFrom > this.ValidTo)
    {
        ret = checkFailed("From date cannot be later than To date.");
    }

    if (ret)
    {
        ret = this.validateCalendar();
    }

    return ret;
}

public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ret = super(_fieldIdToCheck);

    if (!ret)
    {
        return false;
    }

    switch (_fieldIdToCheck)
    {
        case fieldNum(NVHcmWorkerPositionCalendar, CalendarId):

            if (this.CalendarId && !this.CalendarDataAreaId)
            {
                ret = checkFailed("Calendar legal entity is required.");
            }

            break;

        case fieldNum(NVHcmWorkerPositionCalendar, EmploymentCoefficient):

            if (this.EmploymentCoefficient <= 0)
            {
                ret = checkFailed("Employment coefficient must be greater than zero.");
            }

            break;

        case fieldNum(NVHcmWorkerPositionCalendar, ValidFrom):
        case fieldNum(NVHcmWorkerPositionCalendar, ValidTo):

            if (this.ValidFrom &&
                this.ValidTo &&
                this.ValidFrom > this.ValidTo)
            {
                ret = checkFailed("From date cannot be later than To date.");
            }

            break;
    }

    return ret;
}

private boolean validateCalendar()
{
    WorkCalendarTable workCalendarTable;
    DataAreaId        calendarDataAreaId;

    if (!this.CalendarDataAreaId ||
        !this.CalendarId)
    {
        return true;
    }

    calendarDataAreaId = this.CalendarDataAreaId;

    changecompany (calendarDataAreaId)
    {
        select firstonly RecId from workCalendarTable
            where workCalendarTable.CalendarId == this.CalendarId;
    }

    if (!workCalendarTable.RecId)
    {
        return checkFailed(
            strFmt(
                "Calendar %1 does not exist in legal entity %2.",
                this.CalendarId,
                this.CalendarDataAreaId));
    }

    return true;
}

public static NVHcmWorkerPositionCalendar findByDate(
    HcmWorkerRecId _workerRecId,
    TransDate      _date = 0,
    boolean        _forUpdate = false)
{
    NVHcmWorkerPositionCalendar workerPositionCalendar;

    if (!_date)
    {
        _date = systemDateGet();
    }

    workerPositionCalendar.selectForUpdate(_forUpdate);

    select firstonly workerPositionCalendar
        order by ValidFrom desc
        where workerPositionCalendar.Worker     == _workerRecId
           && workerPositionCalendar.ValidFrom  <= _date
           && workerPositionCalendar.ValidTo    >= _date;

    return workerPositionCalendar;
}

public static NVHcmWorkerPositionCalendar findCurrent(
    HcmWorkerRecId _workerRecId,
    boolean        _forUpdate = false)
{
    return NVHcmWorkerPositionCalendar::findByDate(
        _workerRecId,
        systemDateGet(),
        _forUpdate);
}

public static CalendarId calendarIdByDate(
    HcmWorkerRecId _workerRecId,
    TransDate      _date = 0)
{
    return NVHcmWorkerPositionCalendar::findByDate(
        _workerRecId,
        _date).CalendarId;
}

public static DataAreaId calendarDataAreaIdByDate(
    HcmWorkerRecId _workerRecId,
    TransDate      _date = 0)
{
    return NVHcmWorkerPositionCalendar::findByDate(
        _workerRecId,
        _date).CalendarDataAreaId;
}

public static real coefficientByDate(
    HcmWorkerRecId _workerRecId,
    TransDate      _date = 0)
{
    NVHcmWorkerPositionCalendar workerPositionCalendar;

    workerPositionCalendar =
        NVHcmWorkerPositionCalendar::findByDate(
            _workerRecId,
            _date);

    return workerPositionCalendar.RecId
        ? workerPositionCalendar.EmploymentCoefficient
        : 0;
}

public static NVHcmWorkerPositionCalendar find(
    HcmWorkerRecId _workerRecId,
    TransDate      _validFrom,
    boolean        _forUpdate = false)
{
    NVHcmWorkerPositionCalendar workerCalendar;

    workerCalendar.selectForUpdate(_forUpdate);

    select firstonly workerCalendar
    where workerCalendar.Worker    == _workerRecId
       && workerCalendar.ValidFrom == _validFrom;

    return workerCalendar;
}
